From f788eb9bd3453085b67e60787cafd3df2cf8502d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:34:45 +0100
Subject: [PATCH] applets/digital-clock: show the events of the following week
 in the agenda

The agenda only listed the events of the selected day, so upcoming events
were only visible by clicking each day. It now lists the selected day and
the six days after it, grouped under a header for each day with events.

BUG: 410720
---
 applets/digital-clock/CalendarView.qml | 102 ++++++++++++++++---------
 components/calendar/daysmodel.cpp      |  15 +++-
 2 files changed, 79 insertions(+), 38 deletions(-)

diff --git a/applets/digital-clock/CalendarView.qml b/applets/digital-clock/CalendarView.qml
index 48d5dcccb7..af135a2e8a 100644
--- a/applets/digital-clock/CalendarView.qml
+++ b/applets/digital-clock/CalendarView.qml
@@ -178,16 +178,34 @@ PlasmaExtras.Representation {
                 return Qt.formatDate(date, format);
             }

-            function dateEquals(date1: date, date2: date): bool {
-                // QDate is exposed to QML as midnight UTC, while MonthView's
-                // current date is constructed in the local time zone.
-                return date1.getUTCFullYear() === date2.getFullYear()
-                    && date1.getUTCMonth() === date2.getMonth()
-                    && date1.getUTCDate() === date2.getDate();
+            function sectionTitle(day: date): string {
+                const today = new Date(monthView.today.getFullYear(), monthView.today.getMonth(), monthView.today.getDate());
+                const daysFromToday = Math.round((day - today) / 86400000); // 24hrs in ms
+                if (daysFromToday === 0) {
+                    return i18nc("@title:group agenda section", "Today");
+                } else if (daysFromToday === 1) {
+                    return i18nc("@title:group agenda section", "Tomorrow");
+                }
+                return day.toLocaleDateString(Qt.locale(), Locale.LongFormat);
             }

+            // Show the events of the current date and of the six days after it
             function updateEventsForCurrentDate() {
-                eventsList.model = monthView.daysModel.eventsForDate(monthView.currentDate);
+                const entries = [];
+                const shownEvents = new Set();
+                for (let i = 0; i < 7; ++i) {
+                    const day = new Date(monthView.currentDate.getFullYear(), monthView.currentDate.getMonth(), monthView.currentDate.getDate() + i);
+                    const section = sectionTitle(day);
+                    for (const event of monthView.daysModel.eventsForDate(day)) {
+                        // Events spanning several days are only listed on the first one
+                        const key = [event.title, event.startDateTime.getTime(), event.endDateTime.getTime()].join("\n");
+                        if (!shownEvents.has(key)) {
+                            shownEvents.add(key);
+                            entries.push({ event, day, section });
+                        }
+                    }
+                }
+                eventsList.model = entries;
             }

             Connections {
@@ -202,9 +220,7 @@ PlasmaExtras.Representation {
                 target: monthView.daysModel

                 function onAgendaUpdated(updatedDate: date) {
-                    if (agenda.dateEquals(updatedDate, monthView.currentDate)) {
-                        agenda.updateEventsForCurrentDate();
-                    }
+                    agenda.updateEventsForCurrentDate();
                 }
             }

@@ -244,11 +260,23 @@ PlasmaExtras.Representation {
                         currentIndex = -1;
                     }

+                    section.property: "section"
+                    section.delegate: PlasmaExtras.ListSectionHeader {
+                        required property string section
+
+                        width: ListView.view.width
+                        leftPadding: calendar.paddings
+                        text: section
+                    }
+
                     delegate: PlasmaComponents.ItemDelegate {
                         id: eventItem

+                        required property var modelData
                         // Crashes if the type is declared as eventData (which is Q_GADGET)
-                        required property /*PlasmaCalendar.eventData*/var modelData
+                        readonly property /*PlasmaCalendar.eventData*/var eventData: modelData.event
+                        // The day of the section this event is listed in
+                        readonly property date day: modelData.day

                         width: ListView.view.width

@@ -257,28 +285,28 @@ PlasmaExtras.Representation {
                         text: eventTitle.text
                         hoverEnabled: true
                         highlighted: ListView.isCurrentItem
-                        Accessible.description: modelData.description
+                        Accessible.description: eventData.description
                         readonly property bool hasTime: {
                             // Explicitly all-day event
-                            if (modelData.isAllDay) {
+                            if (eventData.isAllDay) {
                                 return false;
                             }
-                            // Multi-day event which does not start or end today (so
-                            // is all-day from today's point of view)
-                            if (modelData.startDateTime - monthView.currentDate < 0 &&
-                                modelData.endDateTime - monthView.currentDate > 86400000) { // 24hrs in ms
+                            // Multi-day event which does not start or end on this day (so
+                            // is all-day from this day's point of view)
+                            if (eventData.startDateTime - day < 0 &&
+                                eventData.endDateTime - day > 86400000) { // 24hrs in ms
                                 return false;
                             }

                             // Non-explicit all-day event
-                            const startIsMidnight = modelData.startDateTime.getHours() === 0
-                                && modelData.startDateTime.getMinutes() === 0;
+                            const startIsMidnight = eventData.startDateTime.getHours() === 0
+                                && eventData.startDateTime.getMinutes() === 0;

-                            const endIsMidnight = modelData.endDateTime.getHours() === 0
-                                && modelData.endDateTime.getMinutes() === 0;
+                            const endIsMidnight = eventData.endDateTime.getHours() === 0
+                                && eventData.endDateTime.getMinutes() === 0;

-                            const sameDay = modelData.startDateTime.getDate() === modelData.endDateTime.getDate()
-                                && modelData.startDateTime.getDay() === modelData.endDateTime.getDay();
+                            const sameDay = eventData.startDateTime.getDate() === eventData.endDateTime.getDate()
+                                && eventData.startDateTime.getDay() === eventData.endDateTime.getDay();

                             return !(startIsMidnight && endIsMidnight && sameDay);
                         }
@@ -298,24 +326,24 @@ PlasmaExtras.Representation {
                                 Layout.rowSpan: 2
                                 Layout.fillHeight: true

-                                color: eventItem.modelData.eventColor
+                                color: eventItem.eventData.eventColor
                                 implicitWidth: 5
-                                visible: eventItem.modelData.eventColor !== ""
+                                visible: eventItem.eventData.eventColor !== ""
                             }

                             PlasmaComponents.Label {
                                 id: startTimeLabel

-                                readonly property bool startsToday: eventItem.modelData.startDateTime - monthView.currentDate >= 0
-                                readonly property bool startedYesterdayLessThan12HoursAgo: eventItem.modelData.startDateTime - monthView.currentDate >= -43200000 //12hrs in ms
+                                readonly property bool startsToday: eventItem.eventData.startDateTime - eventItem.day >= 0
+                                readonly property bool startedYesterdayLessThan12HoursAgo: eventItem.eventData.startDateTime - eventItem.day >= -43200000 //12hrs in ms

                                 Layout.row: 0
                                 Layout.column: 1
                                 Layout.minimumWidth: dateLabelMetrics.width

                                 text: startsToday || startedYesterdayLessThan12HoursAgo
-                                    ? Qt.formatTime(eventItem.modelData.startDateTime)
-                                    : agenda.formatDateWithoutYear(eventItem.modelData.startDateTime)
+                                    ? Qt.formatTime(eventItem.eventData.startDateTime)
+                                    : agenda.formatDateWithoutYear(eventItem.eventData.startDateTime)
                                 textFormat: Text.PlainText
                                 horizontalAlignment: Qt.AlignRight
                                 visible: eventItem.hasTime
@@ -324,8 +352,8 @@ PlasmaExtras.Representation {
                             PlasmaComponents.Label {
                                 id: endTimeLabel

-                                readonly property bool endsToday: eventItem.modelData.endDateTime - monthView.currentDate <= 86400000 // 24hrs in ms
-                                readonly property bool endsTomorrowInLessThan12Hours: eventItem.modelData.endDateTime - monthView.currentDate <= 86400000 + 43200000 // 36hrs in ms
+                                readonly property bool endsToday: eventItem.eventData.endDateTime - eventItem.day <= 86400000 // 24hrs in ms
+                                readonly property bool endsTomorrowInLessThan12Hours: eventItem.eventData.endDateTime - eventItem.day <= 86400000 + 43200000 // 36hrs in ms

                                 Layout.row: 1
                                 Layout.column: 1
@@ -333,8 +361,8 @@ PlasmaExtras.Representation {
                                 Layout.minimumWidth: dateLabelMetrics.width

                                 text: endsToday || endsTomorrowInLessThan12Hours
-                                    ? Qt.formatTime(eventItem.modelData.endDateTime)
-                                    : agenda.formatDateWithoutYear(eventItem.modelData.endDateTime)
+                                    ? Qt.formatTime(eventItem.eventData.endDateTime)
+                                    : agenda.formatDateWithoutYear(eventItem.eventData.endDateTime)
                                 textFormat: Text.PlainText
                                 horizontalAlignment: Qt.AlignRight
                                 opacity: 0.75
@@ -349,7 +377,7 @@ PlasmaExtras.Representation {
                                 Layout.column: 2
                                 Layout.fillWidth: true

-                                text: eventItem.modelData.title
+                                text: eventItem.eventData.title
                                 textFormat: Text.PlainText
                                 verticalAlignment: Text.AlignVCenter
                                 wrapMode: Text.Wrap
@@ -364,7 +392,7 @@ PlasmaExtras.Representation {
                                 spacing: 0

                                 visible: text.length > 0
-                                text: eventItem.modelData.description
+                                text: eventItem.eventData.description

                                 wrapMode: Text.Wrap

@@ -383,8 +411,8 @@ PlasmaExtras.Representation {

                 iconName: "checkmark"
                 text: monthView.isToday(monthView.currentDate)
-                    ? i18n("No events for today")
-                    : i18n("No events for this day");
+                    ? i18n("No upcoming events")
+                    : i18n("No events for this day or the following week");
             }
         }

diff --git a/components/calendar/daysmodel.cpp b/components/calendar/daysmodel.cpp
index 60de15b2ff..04f0a8ab3d 100644
--- a/components/calendar/daysmodel.cpp
+++ b/components/calendar/daysmodel.cpp
@@ -184,7 +184,8 @@ void DaysModel::update()
         const QDate modelFirstDay(d->data->at(0).yearNumber, d->data->at(0).monthNumber, d->data->at(0).dayNumber);
         const auto plugins = d->pluginsManager->plugins();
         for (CalendarEvents::CalendarEventsPlugin *eventsPlugin : plugins) {
-            eventsPlugin->loadEventsForDateRange(modelFirstDay, modelFirstDay.addDays(42));
+            // One more week, so the agenda can list the week after the last displayed day
+            eventsPlugin->loadEventsForDateRange(modelFirstDay, modelFirstDay.addDays(42 + 7));
         }
     }

@@ -195,6 +196,15 @@ void DaysModel::update()
 void DaysModel::onDataReady(const QMultiHash<QDate, CalendarEvents::EventData> &data)
 {
     d->eventsData.reserve(d->eventsData.size() + data.size());
+    if (!d->data->isEmpty()) {
+        const DayData &lastData = d->data->constLast();
+        const QDate modelLastDay(lastData.yearNumber, lastData.monthNumber, lastData.dayNumber);
+        for (auto it = data.cbegin(); it != data.cend(); ++it) {
+            if (it.key() > modelLastDay) {
+                d->eventsData.insert(it.key(), it.value());
+            }
+        }
+    }
     for (int i = 0; i < d->data->count(); i++) {
         const DayData &currentData = d->data->at(i);
         const QDate currentDate(currentData.yearNumber, currentData.monthNumber, currentData.dayNumber);
@@ -376,6 +386,9 @@ QModelIndex DaysModel::indexForDate(const QDate &date)
     const QDate firstDate(firstDay.yearNumber, firstDay.monthNumber, firstDay.dayNumber);

     qint64 daysTo = firstDate.daysTo(date);
+    if (daysTo < 0 || daysTo >= d->data->count()) {
+        return {};
+    }

     return createIndex(daysTo, 0);
 }
